  private void tryItemHorseTickEffects(EntityTickEvent.Pre event) {
    if (!(event.getEntity() instanceof AbstractHorse horse)) {
      return;
    }
    boolean prismarine = horse.getPersistentData().getBoolean(ItemHorsePrismarineWater.NBT_KEY);
    if (prismarine && horse.isInWater()) {
      if (horse.getAirSupply() < horse.getMaxAirSupply()) {
        horse.setAirSupply(horse.getMaxAirSupply());
      }
      if (!horse.hasEffect(MobEffects.DOLPHINS_GRACE)) {
        horse.addEffect(new MobEffectInstance(MobEffects.DOLPHINS_GRACE, 40, 0, false, false, false));
      }
      for (Entity passenger : horse.getPassengers()) {
        if (passenger instanceof LivingEntity rider && !rider.hasEffect(MobEffects.DOLPHINS_GRACE)) {
          rider.addEffect(new MobEffectInstance(MobEffects.DOLPHINS_GRACE, 40, 0, false, false, false));
        }
      }
    }
    // Prismarine: rain runner — speed boost while it's raining
    if (prismarine && horse.level().isRaining() && horse.level().canSeeSky(horse.blockPosition())) {
      if (!horse.hasEffect(MobEffects.MOVEMENT_SPEED)) {
        horse.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 40, 0, false, false, false));
      }
    }
    if (horse.isOnFire()
        && horse.getPersistentData().getBoolean(ItemHorseNetheriteFire.NBT_KEY)) {
      horse.clearFire();
    }
    // Copper: mob radar — glow nearby hostile mobs while horse is ridden
    if (horse.getPersistentData().getBoolean(ItemHorseCopperRadar.NBT_KEY)
        && horse.isVehicle()
        && !horse.level().isClientSide()
        && horse.tickCount % Const.TICKS_PER_SEC == 0) {
      AABB box = horse.getBoundingBox().inflate(16);
      for (Monster mob : horse.level().getEntitiesOfClass(Monster.class, box)) {
        mob.addEffect(new MobEffectInstance(MobEffects.GLOWING, 40, 0, false, false, true));
      }
    }
  }

  private void tryItemHorseEnder(EntityTickEvent.Pre event) {
    if(event.getEntity() instanceof LivingEntity liv)
    if (liv.getPersistentData().contains(ItemHorseEnder.NBT_KEYACTIVE)
        && liv.getPersistentData().getInt(ItemHorseEnder.NBT_KEYACTIVE) > 0) {
      // 
      if (liv.isInWater()

          && liv.getAirSupply() < liv.getMaxAirSupply()
          && !liv.hasEffect(MobEffects.WATER_BREATHING)) {
        liv.addEffect(new MobEffectInstance(MobEffects.WATER_BREATHING, Const.TICKS_PER_SEC * 60, 4, false, false, false));
        liv.addEffect(new MobEffectInstance(PotionEffectRegistry.SWIMSPEED, Const.TICKS_PER_SEC * 60, 1, false, false, false));
        ItemHorseEnder.onSuccess(liv);
      }
      if (liv.isOnFire()
          && !liv.hasEffect(MobEffects.FIRE_RESISTANCE)) {
        liv.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, Const.TICKS_PER_SEC * 60, 4, false, false, false));
        liv.clearFire();
        ItemHorseEnder.onSuccess(liv);
      }
      if (liv.fallDistance > 12
          && !liv.hasEffect(MobEffects.SLOW_FALLING)) {
        liv.addEffect(new MobEffectInstance(MobEffects.SLOW_FALLING, Const.TICKS_PER_SEC * 60, 4, false, false, false));

        ItemHorseEnder.onSuccess(liv);
      }
      if (liv.getHealth() < 6
          && !liv.hasEffect(MobEffects.ABSORPTION)) {
        liv.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, Const.TICKS_PER_SEC * 60, 4, false, false, false));
        liv.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, Const.TICKS_PER_SEC * 60, 4, false, false, false));
        ItemHorseEnder.onSuccess(liv);
      }
    }
  }

  @SubscribeEvent
  public void onBonemealEvent(BonemealEvent event) {
    Level world = event.getLevel();
    BlockPos pos = event.getPos();
    BlockState state = world.getBlockState(pos);

    if (state.getBlock() == BlockRegistry.FLOWER_CYAN.get()) {
      event.setSuccessful(true);
      consumeBonemeal(event);
      if (world.random.nextDouble() < 0.5) {
        ItemStackUtil.drop(world, pos, new ItemStack(BlockRegistry.FLOWER_CYAN.get()));
      }
    }
    else if (state.getBlock() == BlockRegistry.FLOWER_PURPLE_TULIP.get()) {
      event.setSuccessful(true);
      consumeBonemeal(event);
      if (world.random.nextDouble() < 0.25) {
        ItemStackUtil.drop(world, pos, new ItemStack(BlockRegistry.FLOWER_PURPLE_TULIP.get()));
      }
    }
    else if (state.getBlock() == BlockRegistry.FLOWER_ABSALON_TULIP.get()) {
      event.setSuccessful(true);
      consumeBonemeal(event);
      if (world.random.nextDouble() < 0.25) {
        ItemStackUtil.drop(world, pos, new ItemStack(BlockRegistry.FLOWER_ABSALON_TULIP.get()));
      }
    }
    else if (state.getBlock() == BlockRegistry.FLOWER_LIME_CARNATION.get()) {
      event.setSuccessful(true);
      consumeBonemeal(event);
      if (world.random.nextDouble() < 0.25) {
        ItemStackUtil.drop(world, pos, new ItemStack(BlockRegistry.FLOWER_LIME_CARNATION.get()));
      }
    }
  }

  /**
   * setSuccessful(true) cancels the event, which skips ALL vanilla handling for this
   * bonemeal use - including the normal stack shrink - so we have to consume it ourselves.
   * Matches vanilla crop-bonemeal behavior: consumed on every use, creative mode exempt.
   */
  private void consumeBonemeal(BonemealEvent event) {
    Player player = event.getPlayer();
    if (player != null && player.getAbilities().instabuild) {
      return;
    }
    event.getStack().shrink(1);
  }

  @SubscribeEvent
  public void onBedCheck(CanContinueSleepingEvent event) {
    if (event.getEntity() instanceof Player p) {
      if (p.getPersistentData().getBoolean(SleepingMatItem.CYCLIC_SLEEPING)) {
        event.setContinueSleeping(true);
      }
    }
  }

  @SubscribeEvent
  public void onRightClickBlock(PlayerInteractEvent.RightClickBlock event) {
    if (event.getItemStack().isEmpty()) {
      return;
    }
    Player player = event.getEntity();
    if (event.getItemStack().getItem() instanceof ItemScaffolding && player.isCrouching()) {
      scaffoldHit(event);
    }
    if (player.isCrouching() && event.getItemStack().is(DataTags.WRENCH)) {
      if (event.getLevel().getBlockState(event.getPos()).getBlock() instanceof CableBase) {
        player.swing(event.getHand());
        CableBase.crouchClick(event, event.getLevel().getBlockState(event.getPos()));
        event.setCanceled(true);
        SoundUtil.playSound(player, SoundRegistry.THUNK.get(), 0.2F, 1F);
      }
    }
  }

  private void scaffoldHit(PlayerInteractEvent.RightClickBlock event) {
    ItemScaffolding item = (ItemScaffolding) event.getItemStack().getItem();
    Direction opp = event.getFace().getOpposite();
    BlockPos dest = LevelWorldUtil.nextReplaceableInDirection(event.getLevel(), event.getPos(), opp, 16, item.getBlock());
    if (event.getLevel().isEmptyBlock(dest)) {
      event.getLevel().setBlockAndUpdate(dest, item.getBlock().defaultBlockState());
      ItemStack stac = event.getEntity().getItemInHand(event.getHand());
      ItemStackUtil.shrink(event.getEntity(), stac);
      event.setCanceled(true);
    }
  }

