            ResourceLocation.CODEC.encodeStart(NbtOps.INSTANCE, soulEnergy.getEndWalkDimension().location()).resultOrPartial(Goety.LOGGER::error).ifPresent(
                    (p_241148_1_) -> tag.put("EndWalkDim", p_241148_1_));
        }
        return tag;
    }

    public static ISoulEnergy load(CompoundTag tag, ISoulEnergy soulEnergy) {
        soulEnergy.setSEActive(tag.getBoolean("seActive"));
        if (tag.contains("arcax") && tag.contains("arcay") && tag.contains("arcaz")) {
            soulEnergy.setArcaBlock(new BlockPos(tag.getInt("arcax"), tag.getInt("arcay"), tag.getInt("arcaz")));
        }
        if (tag.contains("arcaReviveX") && tag.contains("arcaReviveY") && tag.contains("arcaReviveZ")) {
            soulEnergy.setArcaRevivePos(new BlockPos(tag.getInt("arcaReviveX"), tag.getInt("arcaReviveY"), tag.getInt("arcaReviveZ")));
        }
        if (tag.contains("dimension")) {
            soulEnergy.setArcaBlockDimension(Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, tag.get("dimension")).resultOrPartial(Goety.LOGGER::error).orElse(Level.OVERWORLD));
        } else {
            soulEnergy.setArcaBlockDimension(Level.OVERWORLD);
        }
        if (tag.contains("EndWalkX") && tag.contains("EndWalkY") && tag.contains("EndWalkZ") && tag.contains("EndWalkDim")) {
            soulEnergy.setEndWalkPos(new BlockPos(tag.getInt("EndWalkX"), tag.getInt("EndWalkY"), tag.getInt("EndWalkZ")));
            soulEnergy.setEndWalkDimension(Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, tag.get("EndWalkDim")).resultOrPartial(Goety.LOGGER::error).orElse(Level.OVERWORLD));
        }
        if (tag.contains("miningPosX") && tag.contains("miningPosY") && tag.contains("miningPosZ")) {
            soulEnergy.setMiningPos(new BlockPos(tag.getInt("miningPosX"), tag.getInt("miningPosY"), tag.getInt("miningPosZ")));
        }
        soulEnergy.setSoulEnergy(tag.getInt("soulEnergy"));
        soulEnergy.setRecoil(tag.getInt("recoil"));
        soulEnergy.setRestPeriod(tag.getInt("restPeriod"));
        soulEnergy.setApostleWarned(tag.getBoolean("apostleWarned"));
        soulEnergy.setBottling(tag.getInt("bottling"));
        soulEnergy.setWarding(tag.getInt("warding"));
        soulEnergy.setMaxWarding(tag.getInt("maxWarding"));
        if (tag.contains("BannerBaseColor")) {
            soulEnergy.setBannerBaseColor(DyeColor.byId(tag.getInt("BannerBaseColor")));
        }
        if (tag.contains("BannerPattern")){
            soulEnergy.setBannerPattern(tag.getList("BannerPattern", 10));
        }
        soulEnergy.setTicksInAir(tag.getInt("airTick"));
        soulEnergy.setAirJumps(tag.getInt("airJumps"));
        soulEnergy.setAirJumpCooldown(tag.getInt("airJumpCoolDown"));
        soulEnergy.setMiningProgress(tag.getInt("miningProgress"));
        if (tag.contains("cameraUUID")) {
            soulEnergy.setCameraUUID(tag.getUUID("cameraUUID"));
        } else {
            soulEnergy.setCameraUUID(null);
        }
        replaceAll(soulEnergy.grudgeList(), loadUUIDs(tag, "grudgeList"), soulEnergy::addGrudge, soulEnergy::removeGrudge);
        replaceAll(soulEnergy.grudgeTypeList(), loadTypes(tag, "grudgeTypeList"), soulEnergy::addGrudgeType, soulEnergy::removeGrudgeType);
        replaceAll(soulEnergy.allyList(), loadUUIDs(tag, "allyList"), soulEnergy::addAlly, soulEnergy::removeAlly);
        replaceAll(soulEnergy.allyTypeList(), loadTypes(tag, "allyTypeList"), soulEnergy::addAllyType, soulEnergy::removeAllyType);
        replaceAll(soulEnergy.groundedList(), loadUUIDs(tag, "groundedList"), soulEnergy::addGrounded, soulEnergy::removeGrounded);
        replaceAll(soulEnergy.groundedTypeList(), loadTypes(tag, "groundedTypeList"), soulEnergy::addGroundedType, soulEnergy::removeGroundedType);
        replaceAll(soulEnergy.getResearch(), loadResearch(tag), soulEnergy::addResearch, soulEnergy::removeResearch);
        if (tag.contains("coolDowns", Tag.TAG_LIST)){
            ListTag listTag = (ListTag) tag.get("coolDowns");
            soulEnergy.cooldowns().load(listTag);
        }
        if (tag.contains("coolDownsSpecifics", Tag.TAG_LIST)){
            ListTag listTag2 = (ListTag) tag.get("coolDownsSpecifics");
            soulEnergy.cooldowns().loadSpecifics(listTag2);
        }
        return soulEnergy;
    }
}

package de.teamlapen.vampirism.common.world.blockentity;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import de.teamlapen.vampirism.common.world.inventory.base.PlayerOwnedMenu;
import net.minecraft.core.BlockPos;
import net.minecraft.core.UUIDUtil;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.chat.Component;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.entity.BaseContainerBlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import net.neoforged.neoforge.network.codec.NeoForgeStreamCodecs;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Optional;
import java.util.UUID;

public abstract class PlayerOwnedBlockEntity extends BaseContainerBlockEntity {

    private final LockDataHolder lockDataHolder = new LockDataHolder();

    protected PlayerOwnedBlockEntity(BlockEntityType<?> pType, BlockPos pPos, BlockState pBlockState) {
        super(pType, pPos, pBlockState);
    }

    public void setOwned(Player player) {
        this.lockDataHolder.owner = player.getUUID();
    }

    public static boolean tryAccess(Player player, PlayerOwnedBlockEntity blockEntity, Component displayName) {
        return player.isSpectator() || blockEntity.lockDataHolder.canAccess(player);
    }

    @Override
    public boolean canOpen(@NotNull Player pPlayer) {
        return super.canOpen(pPlayer) && tryAccess(pPlayer, this, this.getName());
    }

    @Override
    protected void saveAdditional(@NotNull ValueOutput output) {
        super.saveAdditional(output);
        this.lockDataHolder.serialize(output.child("lock"));
    }

    @Override
    public void loadAdditional(@NotNull ValueInput input) {
        super.loadAdditional(input);
        this.lockDataHolder.deserialize(input.childOrEmpty("lock"));
    }

    @Override
    protected final @NotNull PlayerOwnedMenu createMenu(int pContainerId, @NotNull Inventory pInventory) {
        return createMenu(pContainerId, pInventory, lockDataHolder);
    }

    protected abstract PlayerOwnedMenu createMenu(int pContainerId, @NotNull Inventory pInventory, @NotNull LockDataHolder lockData);

    public void writeExtraData(FriendlyByteBuf buffer) {
        this.lockDataHolder.writeToBuffer(buffer);
    }

    public static class LockDataHolder implements ValueIOSerializable {
        public static final Codec<LockDataHolder> CODEC = RecordCodecBuilder.create(inst ->
                inst.group(
                        Codec.STRING.xmap(UUID::fromString, UUID::toString).optionalFieldOf("owner").forGetter(l -> java.util.Optional.ofNullable(l.owner)),
                        StringRepresentable.fromEnum(Lock::values).fieldOf("lockStatus").forGetter(LockDataHolder::getLockStatus)
                ).apply(inst, LockDataHolder::new)
        );
        public static final StreamCodec<FriendlyByteBuf, LockDataHolder> STREAM_CODEC = StreamCodec.composite(
                ByteBufCodecs.optional(UUIDUtil.STREAM_CODEC), o -> Optional.ofNullable(o.getOwner()),
                NeoForgeStreamCodecs.enumCodec(Lock.class), LockDataHolder::getLockStatus,
                LockDataHolder::new
        );

        private @Nullable UUID owner;
        private Lock lockStatus = Lock.PUBLIC;

        public LockDataHolder() {
        }

        public LockDataHolder(Lock lockStatus) {
            this.lockStatus = lockStatus;
        }

        @SuppressWarnings("OptionalUsedAsFieldOrParameterType")
        private LockDataHolder(Optional<UUID> owner, Lock lockStatus) {
            this.owner = owner.orElse(null);
            this.lockStatus = lockStatus;
        }

        public @Nullable UUID getOwner() {
            return owner;
        }

        public Lock getLockStatus() {
            return lockStatus;
        }

        public boolean canAccess(Player player) {
            return this.lockStatus == Lock.PUBLIC || this.isOwner(player);
        }

        public boolean isOwner(Player player) {
            return this.owner != null && this.owner.equals(player.getUUID());
        }

        @Override
        public void serialize(ValueOutput output) {
            if (this.owner != null) {
                output.store("owner", UUIDUtil.CODEC, this.owner);
                output.store("lock", Lock.CODEC, this.lockStatus);
            }
        }

        @Override
        public void deserialize(ValueInput input) {
            input.read("owner", UUIDUtil.CODEC).ifPresentOrElse(uuid -> {
                this.owner = uuid;
                this.lockStatus = input.read("lock", Lock.CODEC).orElse(Lock.PUBLIC);
            }, () -> this.lockStatus = Lock.PUBLIC);
        }

        private void writeToBuffer(FriendlyByteBuf buffer) {
            buffer.writeBoolean(this.owner != null);
            if (owner != null) {
                buffer.writeUUID(this.owner);
                buffer.writeEnum(this.lockStatus);
            }
        }

        private void readFromBuffer(FriendlyByteBuf buffer) {
            if (buffer.readBoolean()) {
                this.owner = buffer.readUUID();
                this.lockStatus = buffer.readEnum(Lock.class);
            }
        }

        public static LockDataHolder createFromBuffer(FriendlyByteBuf buffer) {
            var holder = new LockDataHolder();
            holder.readFromBuffer(buffer);
            return holder;
        }

        public void updateStatus(Player player, Lock lockStatus) {
            if (this.isOwner(player)) {
                this.lockStatus = lockStatus;
            }
        }
    }

    public enum Lock implements StringRepresentable {
        PUBLIC("public"),
        PRIVATE("private");

        public static final Codec<Lock> CODEC = StringRepresentable.fromEnum(Lock::values);

        private final String name;

        Lock(String name) {
            this.name = name;
        }

        @Override
        public @NotNull String getSerializedName() {
            return this.name;
        }

        public static Lock get(String key) {
            for (Lock value : values()) {
                if (value.name.equals(key)) {
                    return value;
                }
            }
            return PUBLIC;
        }
    }
}

